mapper.select:
SELECT audit_id, file_id, file_name, action, detail, oper_by, oper_by_user_id, oper_ip, oper_time
FROM sys_file_audit


        AND action = #{query.action}


        AND file_name LIKE CONCAT('%', #{query.fileName}, '%')


        AND oper_by LIKE CONCAT('%', #{query.operBy}, '%')


        AND file_id = #{query.fileId}


        AND oper_time >= #{query.beginTime}


        AND oper_time <= #{query.endTime}


ORDER BY oper_time DESC
